_map:
if (item.symbol && item.p) {
emit(item.symbol, { volume: item.v || 0, price: item.p, firstPrice: item.p, lastPrice: item.p, count: 1 });
}

_reduce:
var total;
if (rereduce === false) {
    total = values.reduce(function (a, b) {
        return {
            volume: a.volume + b.volume,
            firstPrice: a.firstPrice || b.firstPrice,
            lastPrice: b.lastPrice || b.price,
            count: a.count + b.count
        };
    }, { volume: 0, firstPrice: null, lastPrice: 0, count: 0 });
} else {
    total = values.reduce(function (a, b) {
        return {
            volume: a.volume + b.volume,
            firstPrice: a.firstPrice || b.firstPrice,
            lastPrice: b.lastPrice,
            count: a.count + b.count
        };
    }, { volume: 0, firstPrice: null, lastPrice: 0, count: 0 });
}
if (total.firstPrice) {
    total.changePct = ((total.lastPrice - total.firstPrice) / total.firstPrice) * 100;
    total.price = total.lastPrice;
}
emit(total);
